import numpy as np
from qutip import Qobj, qeye, tensor


def static_propagator(
    hamiltonian: Qobj,
    time: float,
) -> Qobj:
    """Return the propagator generated by a time-independent Hamiltonian."""
    return (-1j * hamiltonian * time).expm()


def rotating_frame_propagator(
    propagator: Qobj,
    generator: Qobj,
    time: float,
) -> Qobj:
    """Transform a propagator into a rotating frame."""
    frame = (-1j * generator * time).expm()

    return frame.dag() * propagator


def time_dependent_propagator(
    hamiltonian,
    t0: float,
    t1: float,
    steps: int,
) -> Qobj:
    """Numerically propagate a time-dependent Hamiltonian."""
    if steps <= 0:
        raise ValueError("steps must be positive.")

    dt = (t1 - t0) / steps

    first_hamiltonian = hamiltonian(t0 + dt)
    propagator = qeye(first_hamiltonian.dims[0])

    for step in range(1, steps + 1):
        time = t0 + step * dt
        h_step = hamiltonian(time)

        propagator = (-1j * h_step * dt).expm() * propagator

    return propagator


def rotating_frame_hamiltonian(
    time: float,
    driven_hamiltonian,
    generator: Qobj,
) -> Qobj:
    """Transform a time-dependent Hamiltonian into a rotating frame."""
    frame = (-1j * generator * time).expm()
    hamiltonian = driven_hamiltonian(time)

    return frame.dag() * (hamiltonian - generator) * frame


def transformed_hamiltonian(
    hamiltonian: Qobj,
    transformation: Qobj,
) -> Qobj:
    """Transform a Hamiltonian by a unitary operator."""
    return transformation * hamiltonian * transformation.dag()


def unitary_dynamical_map(
    density_matrix: Qobj,
    propagator: Qobj,
) -> Qobj:
    """Evolve a density matrix under a unitary propagator."""
    return propagator * density_matrix * propagator.dag()


def reduced_dynamical_map(
    density_matrix: Qobj,
    propagator: Qobj,
    environment_state: Qobj,
    keep: list[int],
) -> Qobj:
    """Evolve a system with an environment and trace out unwanted subsystems."""
    initial_state = tensor(
        density_matrix,
        environment_state,
    )

    evolved_state = (
        propagator
        * initial_state
        * propagator.dag()
    )

    return evolved_state.ptrace(keep)


def electron_nuclear_dynamical_map(
    density_matrix: Qobj,
    propagator: Qobj,
    nuclear_states: list[Qobj],
) -> Qobj:
    """Evolve two electrons with interleaved nuclei and trace out the nuclei."""
    if len(nuclear_states) != 2:
        raise ValueError("Two nuclear states must be provided.")

    initial_state = tensor(
        density_matrix,
        nuclear_states[0],
        nuclear_states[1],
    ).permute([0, 2, 1, 3])

    evolved_state = (
        propagator
        * initial_state
        * propagator.dag()
    )

    return evolved_state.ptrace([0, 2])


def logical_electron_nuclear_dynamical_map(
    density_matrix: Qobj,
    propagator: Qobj,
    logical_basis: list[Qobj],
    nuclear_states: list[Qobj],
) -> Qobj:
    """Evolve a logical two-electron state and project back to the logical subspace."""

    if len(logical_basis) != density_matrix.shape[0]:
        raise ValueError(
            "Logical basis size must match the density-matrix dimension."
        )

    isometry = np.column_stack([
        state.full().ravel()
        for state in logical_basis
    ])

    physical_density = Qobj(
        isometry
        @ density_matrix.full()
        @ isometry.conj().T,
        dims=logical_basis[0].proj().dims,
    )

    final_electron_density = electron_nuclear_dynamical_map(
        density_matrix=physical_density,
        propagator=propagator,
        nuclear_states=nuclear_states,
    )

    logical_density = Qobj(
        isometry.conj().T
        @ final_electron_density.full()
        @ isometry,
        dims=density_matrix.dims,
    )

    return logical_density


def hermitian_propagator(hamiltonian: Qobj, time: float) -> Qobj:
    """Propagate a finite Hermitian Hamiltonian through its spectral decomposition."""
    if (
        not hamiltonian.isherm
        or not np.all(np.isfinite(hamiltonian.full()))
        or not np.isfinite(time)
    ):
        raise ValueError("Provide a finite Hermitian Hamiltonian and finite time.")

    energies, states = hamiltonian.eigenstates()
    vectors = np.column_stack([
        state.full().ravel() for state in states
    ])
    phases = np.exp(-1j * np.asarray(energies) * time)
    matrix = np.einsum(
        "ik,k,jk->ij",
        vectors,
        phases,
        vectors.conj(),
        optimize=False,
    )
    return Qobj(matrix, dims=hamiltonian.dims)


def hermitian_time_dependent_propagator(hamiltonian, t0, t1, steps):
    """Propagate a Hermitian Hamiltonian using midpoint spectral exponentials."""
    if not np.all(np.isfinite([t0, t1])) or t1 <= t0:
        raise ValueError("Provide finite increasing time boundaries.")
    if (
        isinstance(steps, (bool, np.bool_))
        or not isinstance(steps, (int, np.integer))
        or steps < 1
    ):
        raise ValueError("steps must be a positive integer.")

    dt = (t1 - t0) / steps
    propagator = None
    for step in range(steps):
        interval = hermitian_propagator(
            hamiltonian(t0 + (step + 0.5) * dt), dt
        )
        propagator = (
            interval if propagator is None else interval * propagator
        )
    return propagator
